from pathlib import Path

# AiAgentChat: optional screen context sent to the server.
p = Path('src/components/ai-agent/AiAgentChat.tsx')
s = p.read_text()
s = s.replace('''  onStrategyPatch,\n  hideActions = false,\n}: {\n  workspaceId: string;\n  module: Module;\n  fullscreen?: boolean;\n  onStrategyPatch?: (patch: Record<string, unknown>) => void;\n  hideActions?: boolean;''', '''  onStrategyPatch,\n  hideActions = false,\n  contextPayload,\n}: {\n  workspaceId: string;\n  module: Module;\n  fullscreen?: boolean;\n  onStrategyPatch?: (patch: Record<string, unknown>) => void;\n  hideActions?: boolean;\n  contextPayload?: Record<string, unknown>;''', 1)
s = s.replace('''            body: { workspaceId, module: agentModule, messages },''', '''            body: { workspaceId, module: agentModule, messages, contextPayload },''', 1)
s = s.replace('''    [workspaceId, agentModule],''', '''    [workspaceId, agentModule, contextPayload],''', 1)
p.write_text(s)

# API: strategist gets real paid-media + CRM context and current editor context.
p = Path('src/routes/api/ai-agent/chat.ts')
s = p.read_text()
s = s.replace('''          | { workspaceId?: string; module?: AgentModule; messages?: unknown }''', '''          | { workspaceId?: string; module?: AgentModule; messages?: unknown; contextPayload?: Record<string, unknown> }''', 1)
old = '''        } else if (moduleName === "strategist") {\n          try {\n            const [{ data: personas }, { data: accts }, { data: strats }] = await Promise.all([\n              ctx.supabase.from("meta_personas").select("id,name,default_objective,ad_account_id").eq("workspace_id", workspaceId),\n              ctx.supabase.from("meta_ad_accounts").select("account_id,name,currency").eq("workspace_id", workspaceId),\n              ctx.supabase.from("meta_strategies").select("id,name,default_objective").eq("workspace_id", workspaceId),\n            ]);\n            const p = ((personas ?? []) as Array<{ name: string; default_objective: string | null }>).map((x) => `- ${x.name}${x.default_objective ? ` (objetivo: ${x.default_objective})` : ""}`).join("\\n") || "  (nenhuma)";\n            const a = ((accts ?? []) as Array<{ account_id: string; name: string; currency: string }>).map((x) => `- ${x.account_id} ${x.name} [${x.currency}]`).join("\\n") || "  (nenhuma)";\n            const s = ((strats ?? []) as Array<{ name: string; default_objective: string | null }>).map((x) => `- ${x.name}${x.default_objective ? ` (${x.default_objective})` : ""}`).join("\\n") || "  (nenhuma ainda)";\n            moduleContext = `Personas disponíveis:\\n${p}\\n\\nContas de anúncio conectadas:\\n${a}\\n\\nEstratégias já criadas neste workspace:\\n${s}`;\n          } catch (e) { moduleContext = `Contexto Estrategista indisponível: ${(e as Error).message}`; }'''
new = '''        } else if (moduleName === "strategist") {\n          try {\n            const [paidMedia, crm, { data: personas }, { data: accts }, { data: strats }] = await Promise.all([\n              buildGestorContext(ctx.supabase, workspaceId).catch((e) => `Mídia paga indisponível: ${(e as Error).message}`),\n              buildCrmContext(ctx.supabase, workspaceId).catch((e) => `CRM indisponível: ${(e as Error).message}`),\n              ctx.supabase.from("meta_personas").select("id,name,description,default_objective,ad_account_id,demographics,locations,detailed_targeting").eq("workspace_id", workspaceId),\n              ctx.supabase.from("meta_ad_accounts").select("account_id,name,currency").eq("workspace_id", workspaceId),\n              ctx.supabase.from("meta_strategies").select("id,name,default_objective,persona_id,ad_account_id,enabled").eq("workspace_id", workspaceId),\n            ]);\n            const p = ((personas ?? []) as Array<{ name: string; description: string | null; default_objective: string | null; ad_account_id: string | null; demographics: unknown; locations: unknown; detailed_targeting: unknown }>).map((x) => `- ${x.name}${x.default_objective ? ` | objetivo=${x.default_objective}` : ""}${x.ad_account_id ? ` | conta=${x.ad_account_id}` : ""} | contexto=${(x.description ?? "").slice(0, 300)} | demografia=${JSON.stringify(x.demographics ?? {})} | localizações=${JSON.stringify(x.locations ?? [])} | targeting=${JSON.stringify(x.detailed_targeting ?? []).slice(0, 700)}`).join("\\n") || "  (nenhuma)";\n            const a = ((accts ?? []) as Array<{ account_id: string; name: string; currency: string }>).map((x) => `- ${x.account_id} ${x.name} [${x.currency}]`).join("\\n") || "  (nenhuma)";\n            const st = ((strats ?? []) as Array<{ name: string; default_objective: string | null; enabled: boolean }>).map((x) => `- ${x.name}${x.default_objective ? ` (${x.default_objective})` : ""} | ${x.enabled ? "ativa" : "pausada"}`).join("\\n") || "  (nenhuma ainda)";\n            const editorContext = body.contextPayload ? JSON.stringify(body.contextPayload).slice(0, 10000) : "(nenhum formulário aberto enviado)";\n            moduleContext = [\n              "## Dados reais atuais de mídia paga", paidMedia,\n              "## Contexto comercial/CRM", crm,\n              `## Personas disponíveis\\n${p}`,\n              `## Contas de anúncio conectadas\\n${a}`,\n              `## Estratégias já criadas\\n${st}`,\n              `## Contexto do formulário de estratégia aberto agora\\n${editorContext}`,\n              "Use as tools de leitura para aprofundar campanhas e criativos antes de propor uma estratégia. Não invente benchmark, meta ou resultado que não esteja no contexto ou briefing.",\n            ].join("\\n\\n");\n          } catch (e) { moduleContext = `Contexto Estrategista indisponível: ${(e as Error).message}`; }'''
if old not in s:
    raise SystemExit('strategist context block not found')
s = s.replace(old, new, 1)
p.write_text(s)

# Strategy editor sends selected/form values to the strategist.
p = Path('src/components/meta/MetaStrategyManager.tsx')
s = p.read_text()
needle = '''          <AiAgentChat\n            workspaceId={workspaceId}\n            module="strategist"'''
replacement = '''          <AiAgentChat\n            workspaceId={workspaceId}\n            module="strategist"\n            contextPayload={{\n              strategyId: form.id ?? null,\n              name: form.name,\n              objective: form.defaultObjective,\n              optimizationGoal: form.optimizationGoal,\n              adAccountId: form.adAccountId,\n              personaId: form.personaId,\n              budgetMode: form.budgetMode,\n              budgetLevel: form.budgetLevel,\n              budgetAmount: form.budgetAmount,\n              bidStrategy: form.bidStrategy,\n              description: form.description,\n              copyGuidelines: form.copyGuidelines,\n              placements: form.placements,\n              schedule: form.schedule,\n              targetingHints: form.targetingHints,\n              automationRules: form.automationRules,\n              linkedPageIds: form.linkedPageIds,\n              linkedIgIds: form.linkedIgIds,\n              linkedWaPhoneIds: form.linkedWaPhoneIds,\n            }}'''
if needle not in s:
    raise SystemExit('AiAgentChat strategist anchor not found')
s = s.replace(needle, replacement, 1)
p.write_text(s)

# Contract regression.
